def _get(data, path):
    """Dotted-path lookup. Returns (found: bool, value)."""
    cur = data
    for part in (path or "").split("."):
        if isinstance(cur, dict) and part in cur:
            cur = cur[part]
        else:
            return False, None
    return True, cur

